mapper.select:
SELECT COUNT(*)
  FROM reservations
 WHERE user_id = #{userId}

SELECT EXISTS (
    SELECT 1
      FROM fairs
     WHERE fair_id = #{fairId}
)

SELECT EXISTS (
    SELECT 1
      FROM reservations
     WHERE fair_id = #{fairId}
       AND user_id = #{userId}
       AND status IN ('PENDING_PAYMENT', 'CONFIRMED', 'CHECKED_IN')
)

SELECT COUNT(*)
 FROM reservations
 WHERE fair_id = #{fairId}
   AND visit_date = #{visitDate}
   AND reservation_type = 'ADVANCE'
   AND status IN ('PENDING_PAYMENT', 'CONFIRMED', 'CHECKED_IN')

SELECT EXISTS (
    SELECT 1
      FROM fair_admin_assignments
     WHERE fair_id = #{fairId}
       AND admin_user_id = #{adminUserId}
)

mapper.insert:
INSERT INTO reservations (
       reservation_no
     , fair_id
     , user_id
     , visit_date
     , reservation_type
     , status
     , reservation_amount
     , reserver_name
     , reserver_phone
     , reserver_email
     , channel
     , agreed_terms
     , reservation_terms_version
     , reservation_terms_agreed_at
     , agreed_privacy
     , agreed_marketing
     , reserved_at
     , payment_expires_at
     , created_at
     , updated_at
) VALUES (
       #{reservationNo}
     , #{fairId}
     , #{userId}
     , #{visitDate}
     , #{reservationType}
     , #{status}
     , #{reservationAmount}
     , #{reserverName}
     , #{reserverPhone}
     , #{reserverEmail}
     , #{channel}
     , #{agreedTerms}
     , #{reservationTermsVersion}
     , #{reservationTermsAgreedAt}
     , FALSE
     , FALSE
     , #{reservedAt}
     , #{paymentExpiresAt}
     , #{createdAt}
     , #{updatedAt}
)
